import pandas as pd
import pytest
from PySide6.QtWidgets import QMessageBox

from piggy_bank import etica
from piggy_bank.etica import COL_DATE, COL_OUT, COL_IN, COL_DESCR, COL_CLASS, COL_RUN_TOT, CLASS_TODO, CUSTOM_CLASSES_CSV

# The *_rc.py modules are generated by `./driver.sh --build-gui`
pytest.importorskip('piggy_bank.ui.main_window_rc', reason='UI not built, run ./driver.sh --build-gui')

from piggy_bank import main_window  # noqa: E402

# No Saturdays: the weekday histogram treats them as an error
ROWS = [('2025-01-02', -10.0, None, 'PIZZA'), ('2025-01-03', None, 100.0, 'SALARY')]


class FakeDialogs:
    """Stands in for QFileDialog and QMessageBox, returning canned answers and recording messages."""
    StandardButton = QMessageBox.StandardButton

    def __init__(self):
        self.path = ''
        self.answer = QMessageBox.StandardButton.Yes
        self.messages = []

    def getOpenFileName(self, *args, **kwargs):
        return self.path, ''

    def getSaveFileName(self, *args, **kwargs):
        return self.path, ''

    def question(self, *args, **kwargs):
        self.messages.append(('question', args[2]))
        return self.answer

    def critical(self, *args, **kwargs):
        self.messages.append(('critical', args[2]))

    def warning(self, *args, **kwargs):
        self.messages.append(('warning', args[2]))


@pytest.fixture
def dialogs(monkeypatch):
    fake = FakeDialogs()
    monkeypatch.setattr(main_window, 'QFileDialog', fake)
    monkeypatch.setattr(main_window, 'QMessageBox', fake)
    return fake


@pytest.fixture
def downloads(tmp_path_factory):
    """A folder outside DATA_DIR, where files to import come from."""
    return tmp_path_factory.mktemp('downloads')


@pytest.fixture
def window(qtbot, write_csv, dialogs):
    write_csv('estrattocontoitalia-2025.csv', ROWS)
    w = main_window.MainWindow()
    qtbot.addWidget(w)
    return w


def column(w, name) -> list:
    table = w.ui_ledger.qtw_ledger
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == name)
    return sorted(table.item(r, col).text() for r in range(table.rowCount()))


def fake_xls(monkeypatch, rows):
    # An xls export is source data: Italian headers
    df = pd.DataFrame(rows, columns=list(etica.SOURCE_COLUMNS))
    monkeypatch.setattr(etica.pd, 'read_excel', lambda path: df.copy())


def visible_descriptions(w) -> list:
    table = w.ui_ledger.qtw_ledger
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == COL_DESCR)
    return sorted(table.item(r, col).text() for r in range(table.rowCount()) if not table.isRowHidden(r))


def test_starts_on_ledger_tab(window):
    # main_window.ui may be saved with another current tab
    assert window.tabWidget.currentWidget() is window.tab_ledger


def test_every_tab_hosts_its_widget(window):
    """Each sub-widget sits in its own tab, so a layout or tab lost in Designer shows up here."""
    tab_of = {window.ui_ledger: window.tab_ledger, window.ui_plots_lines: window.tab_plots_lines,
              window.ui_plots_stats: window.tab_plots_stats, window.ui_classes: window.tab_classes,
              window.ui_periods: window.tab_periods}
    for widget, tab in tab_of.items():
        assert tab.isAncestorOf(widget), f'{type(widget).__name__} is not in {tab.objectName()}'
    assert window.tabWidget.count() == len(tab_of)


def test_ledger_header_is_english(window):
    # The source statements are Italian, everything the user sees is not
    table = window.ui_ledger.qtw_ledger
    assert [table.horizontalHeaderItem(c).text() for c in range(table.columnCount())] == \
        ['Date', 'Out', 'In', 'Description', 'Class', 'Running Total']


def test_extreme_amounts_with_cents_are_visible(qtbot, write_csv, dialogs):
    # The most negative Out and the largest In have cents: the amount ranges must include them
    write_csv('a.csv', [('2025-01-02', -250.4, None, 'MIN OUT'), ('2025-01-03', -0.35, None, 'MAX OUT'),
                        ('2025-01-06', None, 0.45, 'MIN IN'), ('2025-01-07', None, 1200.9, 'MAX IN')])
    w = main_window.MainWindow()
    qtbot.addWidget(w)

    assert visible_descriptions(w) == ['MAX IN', 'MAX OUT', 'MIN IN', 'MIN OUT']


def test_periods_tab_follows_filters(window):
    periods = window.ui_periods
    periods.qcb_periods_time.setCurrentText('Monthly')
    table = periods.table.qtw_periods
    assert table.rowCount() == 1 and table.item(0, 0).text() == '2025-01'
    assert table.item(0, 4).text() == '2'  # Entries

    window.ft.qle_description.setText('pizza')
    window._apply_filters()
    assert table.item(0, 4).text() == '1'


class TestClassColumn:

    @pytest.fixture
    def window(self, qtbot, write_csv, write_classes, dialogs):
        write_csv('a.csv', ROWS + [('2025-01-06', -50.0, None, 'SOTTOSCRIZIONE FONDI')])
        write_classes(['*,*,*,fondi,investment', '*,*,*,PIZZA,food'])
        w = main_window.MainWindow()
        qtbot.addWidget(w)
        return w

    def test_shown_in_ledger(self, window):
        assert column(window, COL_CLASS) == ['food', 'investment', CLASS_TODO]

    def test_one_checkbox_per_class(self, window):
        assert list(window.ft.class_checkboxes()) == ['food', 'investment', CLASS_TODO]

    @pytest.mark.parametrize('unchecked, expected', [((), ['PIZZA', 'SALARY', 'SOTTOSCRIZIONE FONDI']),
                                                     (('investment',), ['PIZZA', 'SALARY']),
                                                     (('food', CLASS_TODO), ['SOTTOSCRIZIONE FONDI'])])
    def test_checkboxes_filter_on_column(self, window, unchecked, expected):
        for cls in unchecked:
            window.ft.class_checkboxes()[cls].setChecked(False)
        window._apply_filters()

        assert visible_descriptions(window) == expected

    def test_running_total_skips_unchecked(self, window):
        window.ft.class_checkboxes()['investment'].setChecked(False)
        window._apply_filters()

        assert window.df_plot[COL_RUN_TOT].iloc[-1] == pytest.approx(90.0)


    def test_class_tabs_follow_filters(self, window):
        classes = window.ui_classes
        tabs = classes.qtw_tabs
        assert [tabs.tabText(i) for i in range(tabs.count())] == ['food', 'investment', CLASS_TODO]

        window.ft.class_checkboxes()['investment'].setChecked(False)
        window.ft.qle_description.setText('pizza')
        window._apply_filters()

        assert [tabs.tabText(i) for i in range(tabs.count())] == ['food']
        assert classes.class_tables()['food'].qtw_movements.rowCount() == 1


class TestImportData:

    def test_adds_rows_and_converts(self, window, dialogs, downloads, data_dir, monkeypatch):
        fake_xls(monkeypatch, [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2026.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert column(window, COL_DESCR) == ['BREAD', 'PIZZA', 'SALARY']
        assert (data_dir / 'estrattocontoitalia-2026.csv').exists()
        assert not (data_dir / 'estrattocontoitalia-2026.xls').exists()
        assert src.exists()  # the original is copied, not moved
        assert dialogs.messages == []

    def test_cancelled_changes_nothing(self, window, dialogs, data_dir):
        before = sorted(p.name for p in data_dir.iterdir())

        window.qa_import_data.trigger()

        assert sorted(p.name for p in data_dir.iterdir()) == before
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']

    def test_existing_statement_needs_confirmation(self, window, dialogs, downloads, data_dir, monkeypatch):
        fake_xls(monkeypatch, [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2025.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)
        dialogs.answer = QMessageBox.StandardButton.No

        window.qa_import_data.trigger()

        assert dialogs.messages[0][0] == 'question'
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']
        assert not (data_dir / 'estrattocontoitalia-2025.xls').exists()

    def test_existing_statement_replaced_when_confirmed(self, window, dialogs, downloads, data_dir, monkeypatch):
        # e.g. a newer export of the current year, which is a superset of the previous one
        fake_xls(monkeypatch, ROWS + [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2025.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert column(window, COL_DESCR) == ['BREAD', 'PIZZA', 'SALARY']

    def test_unreadable_xls_rolls_back(self, window, dialogs, downloads, data_dir, monkeypatch):
        def broken(path):
            raise ValueError('not an excel file')
        monkeypatch.setattr(etica.pd, 'read_excel', broken)
        src = downloads / 'garbage.xls'
        src.write_bytes(b'garbage')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert dialogs.messages[0][0] == 'critical'
        assert not (data_dir / 'garbage.xls').exists()
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']


class TestImportCustomClasses:
    """The qa_import_custom_classes action imports custom-classes.csv, which superseded blacklist.csv."""

    def test_overwrites_and_refreshes(self, window, dialogs, downloads, data_dir, write_classes):
        write_classes(['*,*,*,SALARY,income'])
        window._reload_data()
        assert column(window, COL_CLASS) == ['income', CLASS_TODO]

        src = downloads / 'my-classes.csv'
        src.write_text('Date,Out,In,Description,Class\n2025-01-02,-10,,pizza,food\n')
        dialogs.path = str(src)

        window.qa_import_custom_classes.trigger()

        assert (data_dir / CUSTOM_CLASSES_CSV).read_text() == src.read_text()
        assert column(window, COL_CLASS) == ['food', CLASS_TODO]
        assert list(window.ft.class_checkboxes()) == ['food', CLASS_TODO]
        assert dialogs.messages == []

    def test_invalid_file_restores_previous(self, window, dialogs, downloads, data_dir, write_classes):
        previous = write_classes(['*,*,*,SALARY,income']).read_text()
        window._reload_data()

        # Wrong header -> cluster_custom() raises
        src = downloads / 'not-rules.csv'
        src.write_text('Date,Out,In,Description\n*,*,*,PIZZA\n')
        dialogs.path = str(src)

        window.qa_import_custom_classes.trigger()

        assert dialogs.messages[0][0] == 'critical'
        assert (data_dir / CUSTOM_CLASSES_CSV).read_text() == previous
        assert column(window, COL_CLASS) == ['income', CLASS_TODO]


class TestExportData:

    def test_copies_merged_csv(self, window, dialogs, downloads, data_dir):
        dst = downloads / 'export.csv'
        dialogs.path = str(dst)

        window.qa_export_data.trigger()

        assert dst.read_text() == (data_dir / 'merged.csv').read_text()

    def test_cancelled_writes_nothing(self, window, dialogs, downloads):
        window.qa_export_data.trigger()

        assert list(downloads.iterdir()) == []
